    others = clips.filter((x) => x !== c).map((x) => ({ s: x.timelineStart, e: x.timelineStart + length(x) })),
    prevEnd = Math.max(0, ...others.filter((o) => o.e <= s0 + 0.001).map((o) => o.e)),
