document.addEventListener("keydown", (e) => {
  if (!editorIsVisible() || busy || /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
    e.preventDefault();
    restore(e.shiftKey ? future : history, e.shiftKey ? history : future);
  } else if (e.key === "Delete") {
    e.preventDefault();
    $("remove").click();
  } else if (!e.ctrlKey && !e.metaKey && e.key.toLowerCase() === "s") {
    e.preventDefault();
    splitClip();
  }
});

function baseFilterCSS(name) {
  return (
    {
      original: "",
      mono: "grayscale(1)",
      warm: "sepia(.35) saturate(1.25)",
      cool: "hue-rotate(20deg) saturate(.85)",
      vivid: "saturate(1.65) contrast(1.1)",
      retro: "sepia(.7) contrast(.9)",
      soft: "contrast(.85) saturate(.8)",
    }[name] || ""
  );
}
function partitionCaptions(left, right, at) {
  let settings = left.stockMotion87 ? { ...left.stockMotion87 } : null;
  let options = (left.optionClips || []).map((o) => ({ ...o, preset: JSON.parse(JSON.stringify(o.preset)) }));
  assignVisualPositions();
  let start = left.timelineStart;
  let originalLength = length(left),
    layers = (left.overlays || []).map((l) => ({ ...l })),
    frames = (left.keyframes || []).map((f) => ({ time: f.time, value: { ...f.value } })),
    startFrame = interpolateFrame(left, 0),
    splitFrame = interpolateFrame(left, at),
    endFrame = interpolateFrame(left, originalLength);
  {
    let windows = Object.fromEntries(
        Object.keys(timingNames)
          .filter((k) => k !== "text")
          .map((k) => [k, optionRange(left, k)]),
      ),
      layers = textLayers(left).map((t) => ({ ...t, ...optionRange(left, "text", t) }));
    captionLayers(left);
    let caps = left.captions || [];
    left.captions = caps.filter((c) => c.start < at).map((c) => ({ ...c, end: Math.min(c.end, at) }));
    right.captions = caps
      .filter((c) => c.end > at)
      .map((c) => ({ ...c, start: Math.max(0, c.start - at), end: c.end - at }));
    right.captions = right.captions.map((t) => ({ ...t, id: crypto.randomUUID(), style: { ...t.style } }));
    left.activeCaptionId = left.captions[0]?.id;
    right.activeCaptionId = right.captions[0]?.id;
    let cut = (r, shift, max) => ({
      start: Math.max(0, Math.min(max, r.start - shift)),
      end: Math.max(0, Math.min(max, r.end - shift)),
    });
    left.optionTimes = Object.fromEntries(Object.entries(windows).map(([k, r]) => [k, cut(r, 0, at)]));
    right.optionTimes = Object.fromEntries(Object.entries(windows).map(([k, r]) => [k, cut(r, at, length(left) - at)]));
    left.textLayers = layers.map((t) => ({ ...t, ...cut(t, 0, at), style: { ...t.style } }));
    right.textLayers = layers.map((t) => ({ ...t, ...cut(t, at, length(left) - at), style: { ...t.style } }));
  }
  left.overlays = layers
    .filter((l) => l.start < at)
    .map((l) => ({ ...l, end: Math.min(at, l.end), transform: { ...l.transform } }));
  right.overlays = layers
    .filter((l) => l.end > at)
    .map((l) => ({
      ...l,
      start: Math.max(0, l.start - at),
      end: l.end - at,
      sourceOffset: (l.sourceOffset || 0) + Math.max(0, at - l.start),
      transform: { ...l.transform },
    }));
  if (frames.length) {
    left.keyframes = [
      { time: 0, value: startFrame },
      ...frames.filter((f) => f.time > 0 && f.time < at),
      { time: at, value: splitFrame },
    ];
    right.keyframes = [
      { time: 0, value: splitFrame },
      ...frames.filter((f) => f.time > at).map((f) => ({ ...f, time: f.time - at })),
      { time: originalLength - at, value: endFrame },
    ];
  }
  right.transform = left.transform ? { ...left.transform } : undefined;
  right.colorGrade = left.colorGrade ? { ...left.colorGrade } : undefined;
  right.chroma = left.chroma ? { ...left.chroma } : undefined;
  left.timelineStart = start;
  right.timelineStart = start + at;
  left.optionClips = options.filter((o) => o.start < at).map((o) => ({ ...o, end: Math.min(o.end, at) }));
  right.optionClips = options
    .filter((o) => o.end > at)
    .map((o) => ({ ...o, id: crypto.randomUUID(), start: Math.max(0, o.start - at), end: o.end - at }));
  left.activeOptionId = left.optionClips[0]?.id;
  right.activeOptionId = right.optionClips[0]?.id;
  if (settings) {
    left.stockMotion87 = { ...settings };
    right.stockMotion87 = { ...settings, timeOffset87: (settings.timeOffset87 || 0) + at };
  }
}
