    const all=await archiveRun222('getAll'),existing=all.filter(r=>r.type222==='revision'&&r.owner222===data.id),assets=new Map(all.filter(r=>r.type222==='asset').map(r=>[r.id,r])),refs=new Set(),blobRefs=new Map();
