        const mediaId=parent?.mediaId||(path.startsWith('root.mediaLibrary.')?parent?.id:null)||(candidates.length===1?candidates[0].id:null);
        const id='@cm-asset222:'+data.id+':'+(mediaId||crypto.randomUUID())+':'+value.size+':'+value.type;
