    format: "frame-studio",
    version: 1,
    id: activeProjectId || crypto.randomUUID(),
    name: $("projectName").value.trim() || "새 프로젝트",
    modified: Date.now(),
    ratio: $("ratio").value,
    quality: $("quality").value,
