async function saveTemplate() {
  if (busy || projectOperation) return;
  if (!clips.length) {
    homeStatus("먼저 편집 화면에서 구간을 선택하세요.");
    status("먼저 구간을 선택하세요.");
    return;
  }
  let title = await askName(
    "템플릿 저장",
    "현재 화면 비율과 선택한 구간의 스타일을 저장합니다. 미디어는 포함하지 않습니다.",
    "나의 템플릿",
  );
  if (title === null) return;
  let c = clips[selected >= 0 ? selected : 0],
    preset = props(c);
  for (let key of ["name", "kind", "start", "end", "captions"]) delete preset[key];
  let all = templates();
  all.push({ name: title || "나의 템플릿", ratio: $("ratio").value, preset });
  try {
    localStorage.setItem("FrameStudioTemplates", JSON.stringify(all));
    renderTemplates();
    status("템플릿을 저장했습니다.");
    homeStatus("템플릿을 저장했습니다.");
  } catch {
    status("템플릿을 저장할 공간이 부족합니다.");
  }
}
function defaultQuality() {
  try {
    return localStorage.getItem("FrameStudioQuality") || "720";
  } catch {
    return "720";
  }
}
async function settings() {
  let dialog = document.createElement("dialog");
  dialog.className = "dialog-shade";
  let title = document.createElement("h2");
  title.textContent = "환경설정";
  let p = document.createElement("p");
  p.textContent =
    "새 프로젝트의 기본 출력 화질을 선택하세요. 프로젝트는 이 브라우저에 저장됩니다. 브라우저 데이터를 지우면 목록이 사라지므로 프로젝트 파일로도 보관할 수 있습니다.";
  let select = document.createElement("select");
  for (let [v, label] of [
    ["720", "720p HD"],
    ["1080", "1080p FHD"],
  ]) {
    let o = document.createElement("option");
    o.value = v;
    o.textContent = label;
    select.append(o);
  }
  select.value = defaultQuality();
  let done = document.createElement("button");
  done.textContent = "저장";
  done.className = "primary";
  done.onclick = () => {
    try {
      localStorage.setItem("FrameStudioQuality", select.value);
      homeStatus("기본 화질 설정을 저장했습니다.");
    } catch {
      homeStatus("설정을 저장할 수 없습니다.");
    }
    dialog.close();
    dialog.remove();
  };
  dialog.oncancel = () => dialog.remove();
  dialog.append(title, p, select, done);
  document.body.append(dialog);
  dialog.showModal();
}
function blobData(blob) {
  return new Promise((resolve, reject) => {
    let reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(Error("파일 변환 실패"));
    reader.readAsDataURL(blob);
  });
}
async function exportProjectFile() {
  if (!(busy || projectOperation)) {
    pause();
    operationLock(true);
    homeStatus("중복 원본을 합쳐 프로젝트 파일을 준비합니다…");
    try {
      let packed = await packProject89(await snapshotProject());
      download(
        new Blob([JSON.stringify(packed)], { type: "application/json" }),
        packed.name.replace(/[\/:*?"<>|]/g, "_") + ".clipmood.json",
      );
      status("프로젝트 저장 · 원본 " + packed.mediaFiles.length + "개를 중복 없이 담았습니다.");
      homeStatus("프로젝트 파일을 저장했습니다.");
    } catch (e) {
      status(e.message);
      homeStatus(e.message);
    } finally {
      operationLock(false);
    }
  }
}
async function importProjectFile(file) {
  if (busy || projectOperation) return;
  try {
    let data = JSON.parse(await file.text());
    if (data.format !== "frame-studio" || !Array.isArray(data.clips)) throw Error("프로젝트 파일 형식을 확인하세요.");
    for (let c of data.clips) {
      if (typeof c.media !== "string" || !c.media.startsWith("data:"))
        throw Error("프로젝트 미디어 형식을 확인하세요.");
      c.media = await (await fetch(c.media)).blob();
    }
    if (data.music) {
      if (!data.music.media.startsWith("data:")) throw Error("음악 형식을 확인하세요.");
      data.music.media = await (await fetch(data.music.media)).blob();
    }
    if (data.musicTracks)
      for (let track of data.musicTracks) {
        if (typeof track.media !== "string" || !track.media.startsWith("data:"))
          throw Error("음악 파일 형식을 확인하세요.");
        track.media = await (await fetch(track.media)).blob();
      }
    if (data.mediaLibrary)
      for (let item of data.mediaLibrary) {
        if (typeof item.file !== "string" || !item.file.startsWith("data:"))
          throw Error("미디어 원본 형식을 확인하세요.");
        item.file = await (await fetch(item.file)).blob();
      }
    checkProject(data);
    await loadProject(data);
  } catch (e) {
    homeStatus("불러오기 실패: " + e.message);
    status("불러오기 실패: " + e.message);
  }
}
