// Sound effects are separate timed events, mixed alongside music and original audio.
function syncSoundEvents() {
  for (let event of soundEvents) {
    if (event === processedPreviewTarget && !playing) continue;
    let local = time - event.start,
      inside = playing && local >= 0 && local < event.el.duration;
    if (!inside) {
      event.el.pause();
      continue;
    }
    if (Math.abs(event.el.currentTime - local) > 0.2) event.el.currentTime = local;
    if (event.el.paused) event.el.play().catch((e) => status("효과음 재생 오류: " + e.message));
  }
}
