const titleThumbnailCache = new Map();
function titleThumbnail(item) {
  if (suppliedDesigns229?.isTrot228(item?.style)) return suppliedDesigns229.trotThumb228(item, 240, 130, item.name.split(" · ")[0]);
  if (titleThumbnailCache.has(item.id)) return titleThumbnailCache.get(item.id);
  let c = document.createElement("canvas");
  c.width = 240;
  c.height = 130;
  let x = c.getContext("2d"),
    s = item.style;
  let g = x.createLinearGradient(0, 0, 240, 130);
  g.addColorStop(0, "#081219");
  g.addColorStop(
    1,
    ["fire", "gold"].includes(s.skin) ? "#5d211a" : ["ice", "metal", "chrome"].includes(s.skin) ? "#153955" : "#223951",
  );
  x.fillStyle = g;
  x.fillRect(0, 0, 240, 130);
  for (let n = 0; n < 25; n++) {
    x.fillStyle = ["fire", "gold"].includes(s.skin) ? "#ffa34255" : "#99edff44";
    x.fillRect(seeded(n + 3) * 240, seeded(n + 44) * 130, 2, 2);
  }
  x.textAlign = "center";
  x.font = "bold 22px " + s.font;
  x.lineWidth = 3;
  x.strokeStyle = "#07090d";
  x.shadowColor = s.color;
  x.shadowBlur = ["neon", "fire", "ice"].includes(s.skin) ? 8 : 0;
  x.strokeText(item.name, 120, 72, 218);
  x.fillStyle = s.color;
  x.fillText(item.name, 120, 72, 218);
  let result = c.toDataURL("image/png");
  titleThumbnailCache.set(item.id, result);
  return result;
}

let masterAudio = null;
function masterInput() {
  if (!masterAudio) {
    let input = audioCtx.createGain(),
      limiter = audioCtx.createDynamicsCompressor();
    limiter.threshold.value = -2;
    limiter.knee.value = 2;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.002;
    limiter.release.value = 0.18;
    input.connect(limiter);
    let analyser = audioCtx.createAnalyser();
    analyser.fftSize = 4096;
    analyser.minDecibels = -90;
    analyser.maxDecibels = -15;
    analyser.smoothingTimeConstant = 0.2;
    limiter.connect(analyser);
    analyser.connect(mix);
    analyser.connect(audioCtx.destination);
    masterAudio = { input, limiter, analyser };
  }
  return masterAudio.input;
}
