  rr125(x, -W / 2 + H * 0.06, -H / 2 + H * 0.06, W - H * 0.12, H - H * 0.12, H * 0.22);
  x.fillStyle = "rgba(10,6,22,0.55)";
  x.fill();
  x.lineWidth = H * 0.06;
  x.strokeStyle = d.color;
  x.shadowColor = d.color;
  x.shadowBlur = H * 0.35 * glow;
  x.stroke();
  let text = d.text || "SUBSCRIBE";
  font125(x, 900, H * 0.46, text, W - H * 0.5);
  x.textAlign = "center";
  x.textBaseline = "middle";
  x.lineWidth = H * 0.035;
  x.strokeStyle = d.color;
  x.strokeText(text, 0, H * 0.03);
  x.shadowBlur = H * 0.22 * glow;
  x.fillStyle = "#ffffff";
  x.fillText(text, 0, H * 0.03);
