    let bass = chain(offline.createBiquadFilter());
    bass.type = "lowshelf";
    bass.frequency.value = 180;
    bass.gain.value = settings.bass || 0;
    let treble = chain(offline.createBiquadFilter());
    treble.type = "highshelf";
    treble.frequency.value = 3500;
    treble.gain.value = settings.treble || 0;
    if (settings.ring) {
      let ring = ringModulator119(offline, settings);
      chain(ring.input);
      last = ring.output;
    }
    if (settings.drive) {
      let drive = chain(offline.createWaveShaper());
      drive.curve = driveCurve(settings.drive);
      drive.oversample = "2x";
    }
    let compressor = chain(offline.createDynamicsCompressor());
    compressor.threshold.value = settings.compress ? -24 : -6;
    compressor.knee.value = 18;
    compressor.ratio.value = settings.compress ? 3 : 1;
    compressor.attack.value = 0.01;
    compressor.release.value = 0.18;
    let pan = chain(offline.createStereoPanner());
    pan.pan.value = settings.pan || 0;
    let sum = offline.createGain(),
      dry = offline.createGain();
    dry.gain.value = 1 - Math.max(settings.reverbMix || 0, settings.delayMix || 0) * 0.25;
    last.connect(dry);
    dry.connect(sum);
