      let delay = offline.createDelay(2),
        feedback = offline.createGain(),
        wet = offline.createGain();
      delay.delayTime.value = settings.delay;
      feedback.gain.value = Math.min(0.45, settings.feedback || 0.2);
      wet.gain.value = settings.delayMix || 0;
      last.connect(delay);
      delay.connect(feedback);
      feedback.connect(delay);
      delay.connect(wet);
      wet.connect(sum);
