function syncProPanel() {
  let c = inspectorTarget();
  if (!c) return;
  let tr = { ...basicTransform(), ...c.transform };
  for (let [key, input] of Object.entries(transformInputs)) input.value = key === "rotation" ? tr[key] : tr[key] * 100;
  maskInput.value = tr.mask;
  blendInput.value = tr.blend;
  for (let [key, input] of Object.entries(gradeInputs))
    input.value = c.colorGrade?.[key] ?? (["contrast", "saturation"].includes(key) ? 100 : 0);
  rateInput.value = String(c.rate || 1);
  rateInput.disabled = c.kind !== "video";
  easingInput.value = c.easing || "smooth";
  keyList.replaceChildren();
  for (let frame of c.keyframes || []) {
    let row = document.createElement("div");
    row.className = "actions";
    proButton(row, "key-" + frame.time, frame.time.toFixed(2) + "초 보기", async () => {
      pause();
      c.transform = { ...frame.value };
      await go(offset(selected) + frame.time);
      syncProPanel();
    });
    proButton(row, "key-delete-" + frame.time, "삭제", () => {
      remember();
      c.keyframes = c.keyframes.filter((f) => f !== frame);
      draw();
      syncProPanel();
    });
    keyList.append(row);
  }
  overlaySelect.replaceChildren();
  for (let layer of c.overlays || []) {
    let o = document.createElement("option");
    o.value = layer.id;
    o.textContent = layer.name;
    overlaySelect.append(o);
  }
  overlaySelect.value = c.activeOverlayId || c.overlays?.[0]?.id || "";
  let l = selectedOverlay();
  for (let [key, input] of Object.entries(overlayInputs)) {
    input.disabled = !l;
    if (l)
      input.value = ["start", "end"].includes(key)
        ? l[key]
        : key === "rotation"
          ? l.transform?.[key] || 0
          : (l.transform?.[key] ?? basicTransform()[key]) * 100;
  }
  overlayMask.value = l?.transform?.mask || "none";
  let prior = fadeTarget.value;
  fadeTarget.replaceChildren();
  for (let track of musicTracks) {
    let o = document.createElement("option");
    o.value = track.id;
    o.textContent = track.name;
    fadeTarget.append(o);
  }
  if (c.kind === "video") {
    let o = document.createElement("option");
    o.value = "video";
    o.textContent = "선택한 영상의 소리";
    fadeTarget.append(o);
  }
  let opts = [...fadeTarget.children].map((o) => o.value);
  fadeTarget.value = opts.includes(prior) ? prior : opts[0] || "";
  fadeTarget.onchange();
}
