function isTypingSpace(target) {
  if (!target) return false;
  if (target.isContentEditable || target.closest?.('[contenteditable="true"], [role="textbox"]')) return true;
  return (
    target.tagName === "TEXTAREA" ||
    target.tagName === "SELECT" ||
    (target.tagName === "INPUT" && !["range", "checkbox", "radio", "button", "submit"].includes(target.type))
  );
}
async function toggleSpacePlayback() {
  stopSfx105();
  let wasPlaying = playing;
  for (let el of new Set(
    [audioSource70?.el, processedPreviewTarget?.el, mediaAudition, rawMusicPreview].filter(Boolean),
  ))
    el.pause();
  processedPreviewTarget = null;
  if (wasPlaying) {
    pause();
    paintAudioWorkspace70();
    status("타임라인 일시정지 · Space로 이어서 재생");
  } else {
    await $("play").onclick();
    paintAudioWorkspace70();
  }
}
async function handleSpacePlayback(event) {
  if (
    !(event.code === "Space" || event.key === " ") ||
    event.ctrlKey ||
    event.metaKey ||
    event.altKey ||
    event.isComposing ||
    !editorIsVisible() ||
    busy ||
    projectOperation ||
    isTypingSpace(event.target) ||
    document.querySelector("dialog[open]")
  )
    return;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (event.repeat || spacePlaybackPending) return;
  spacePlaybackPending = true;
  try {
    await toggleSpacePlayback();
  } catch (e) {
    status("음악 재생 실패: " + e.message);
  } finally {
    spacePlaybackPending = false;
  }
}
document.addEventListener("keydown", handleSpacePlayback, true);
