function compactMusicTracks() {
  if (!musicTracks.length) return;
  let ordered = [...musicTracks].sort((a, b) => a.start - b.start),
    cursor = 0;
  musicTracks = ordered.map((track, index) => {
    let overlap = index
      ? Math.min(
          track.fadeIn || 0,
          ordered[index - 1].fadeOut || 0,
          trackDuration(track) / 2,
          trackDuration(ordered[index - 1]) / 2,
        )
      : 0;
    let start = cursor - overlap;
    cursor = start + trackDuration(track);
    return {
      ...track,
      start,
      fadeIn: Math.min(track.fadeIn || 0, trackDuration(track) / 2),
      fadeOut: Math.min(track.fadeOut || 0, trackDuration(track) / 2),
    };
  });
  music = musicTracks[0] || null;
}
