function musicSnap(start, track) {
  let threshold = 10 / pixels,
    points = [0, ...musicTracks.filter((t) => t.id !== track.id).flatMap((t) => [t.start, t.start + trackDuration(t)])],
    best = start,
    min = threshold;
  for (let point of points)
    for (let candidate of [point, point - trackDuration(track)])
      if (candidate >= 0 && Math.abs(candidate - start) < min) {
        min = Math.abs(candidate - start);
        best = candidate;
      }
  return best;
}
function beginVisualMove(e, index, node) {
  if (!busy && !projectOperation && (e.button ?? 0) === 0) {
    selectedTimelineOption = null;
    selectDeleteTarget81("visual", { c: clips[index] });
  }
  if (!(busy || projectOperation || e.button !== 0 || e.shiftKey || e.target?.classList?.contains("trim-handle"))) {
    e.preventDefault();
    e.stopPropagation();
    pause();
    assignVisualPositions();
    timelineSelectionKind = "visual";
    let c = clips[index],
      x = e.clientX,
      old = c.timelineStart,
      moved = false;
    selected = index;
    node.setPointerCapture(e.pointerId);
    function move(ev) {
      let raw = ev.clientX - x;
      if (Math.abs(raw) < 4 && !moved) return;
      if (!moved) remember();
      moved = true;
      c.timelineStart = snapVisualStart(c, old + raw / pixels);
      node.style.left = c.timelineStart * pixels + "px";
      node.style.zIndex = "4";
      node.style.opacity = ".75";
      status(c.name + " · 이동 위치 " + c.timelineStart.toFixed(1) + "초");
    }
    async function finish() {
      node.removeEventListener("pointermove", move);
      node.removeEventListener("pointerup", finish);
      node.removeEventListener("pointercancel", finish);
      node.style.opacity = "";
      if (moved) {
        clips = [...clips].sort((a, b) => a.timelineStart - b.timelineStart);
        selected = clips.indexOf(c);
        await select(selected);
        status("이미지·영상을 " + c.timelineStart.toFixed(1) + "초로 옮겼습니다.");
      } else await select(index);
    }
    node.addEventListener("pointermove", move);
    node.addEventListener("pointerup", finish);
    node.addEventListener("pointercancel", finish);
  }
}
