// 링 모듈레이터: 목소리에 낮은 사인파를 곱해 로봇·외계인처럼 금속성 소리로 바꿉니다.
function ringModulator119(context, settings) {
  let input = context.createGain(),
    output = context.createGain(),
    dry = context.createGain(),
    wet = context.createGain(),
    carrier = context.createGain(),
    osc = context.createOscillator(),
    mix = Math.max(0, Math.min(1, settings.ringMix ?? 1));
  osc.type = "sine";
  osc.frequency.value = settings.ring;
  carrier.gain.value = 0;
  osc.connect(carrier.gain);
  osc.start();
  dry.gain.value = 1 - mix;
  wet.gain.value = mix * 1.4;
  input.connect(dry);
  dry.connect(output);
  input.connect(carrier);
  carrier.connect(wet);
  wet.connect(output);
  return { input, output, nodes: [input, output, dry, wet, carrier, osc] };
}
function studioControl(label, type, value, min, max, step, handler) {
  let wrap = document.createElement("label");
  wrap.className = "studio-audio-control";
  let name = document.createElement("span");
  name.textContent = label;
  let input = document.createElement("input");
  input.type = type;
  input.min = min;
  input.max = max;
  input.step = step;
  if (type === "checkbox") input.checked = !!value;
  else input.value = value;
  input.setAttribute("aria-label", label);
  let output = document.createElement("output");
  output.textContent = type === "checkbox" ? "" : value;
  input.onchange = async () => {
    if (busy || projectOperation) return;
    let v = type === "checkbox" ? input.checked : +input.value;
    if (type !== "checkbox" && !Number.isFinite(v)) return;
    output.textContent = type === "checkbox" ? "" : v;
    try {
      await handler(v);
    } catch (e) {
      status(e.message);
    }
  };
  wrap.append(name, input, output);
  return wrap;
}
