    c.stickerX = original.x;
    c.stickerY = original.y;
    persistGeometryEdit();
    let b = overlayItems(c).find((i) => i.kind === "sticker")?.bounds;
    if (b) {
      let left = sx === 1 ? oppositeX : oppositeX - b.width,
        top = sy === 1 ? oppositeY : oppositeY - b.height;
      c.stickerX += (left - b.x) / canvas.width;
      c.stickerY += (top - b.y) / canvas.height;
    }
