// Canvas hit testing lets template titles move directly, regardless of the open tab.
function previewTextHit(clientX, clientY) {
  let c = clips[current] || previewSample;
  if (!c) return null;
  let r = canvas.getBoundingClientRect();
  if (
    !r.width ||
    !r.height ||
    clientX < r.left ||
    clientX > r.left + r.width ||
    clientY < r.top ||
    clientY > r.top + r.height
  )
    return null;
  let x = ((clientX - r.left) * canvas.width) / r.width,
    y = ((clientY - r.top) * canvas.height) / r.height;
  return (
    overlayItems(c)
      .filter((i) => i.kind === "text" || i.kind === "caption")
      .reverse()
      .find(
        (i) =>
          x >= i.bounds.x && x <= i.bounds.x + i.bounds.width && y >= i.bounds.y && y <= i.bounds.y + i.bounds.height,
      ) || null
  );
}
