function drawWeather53(g, W, H, d, t, speed = 1, thickness = 1, amount = 1) {
  g.save();
  g.scale(W / 1280, H / 720);
  g.shadowBlur = 0;
  g.filter = "none";
  g.lineCap = "round";
  for (let layer = 0; layer < 3; layer++) {
    let count = Math.round((d.kind === "rain" ? [170, 100, 42] : [46, 32, 15])[layer] * d.density * amount);
    for (let n = 0; n < count; n++) {
      let p = particle59(d.kind, n, layer, t * speed, d.wind);
      if (d.kind === "rain") {
        let len = p.size * (0.9 + layer * 0.3),
          tx = p.x - (p.vx / p.vy) * len,
          ty = p.y - len,
          gradient = g.createLinearGradient(tx, ty, p.x, p.y);
        gradient.addColorStop(0, "rgba(180,206,225,0)");
        gradient.addColorStop(0.65, "rgba(188,212,228," + p.alpha * 0.65 + ")");
        gradient.addColorStop(1, "rgba(205,223,236," + p.alpha + ")");
        g.strokeStyle = gradient;
        g.lineWidth = [0.42, 0.68, 0.92][layer] * thickness;
        g.beginPath();
        g.moveTo(tx, ty);
        g.lineTo(p.x, p.y);
        g.stroke();
      } else {
        let r = p.size * thickness,
          gradient = g.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
        gradient.addColorStop(0, "rgba(248,251,255," + p.alpha + ")");
        gradient.addColorStop(0.5, "rgba(237,246,255," + p.alpha * 0.8 + ")");
        gradient.addColorStop(1, "rgba(237,246,255,0)");
        g.fillStyle = gradient;
        g.beginPath();
        g.arc(p.x, p.y, r, 0, Math.PI * 2);
        g.fill();
      }
    }
  }
  g.restore();
}
