    if (!moved) remember();
    moved = true;
    // 되돌리기 기록이 예전 위치를 지키도록, 레이어를 고치지 않고 새 레이어로 바꿉니다.
    let next = {
      ...layer,
      transform: {
        ...start,
        x: Math.max(-0.2, Math.min(1.2, start.x + dx)),
        y: Math.max(-0.2, Math.min(1.2, start.y + dy)),
      },
    };
    c.overlays = c.overlays.map((l) => (l === layer ? next : l));
    layer = next;
    draw();
