// ── 업로드 정보 (제목·설명·태그·챕터) ─────────────────
// 유튜브 챕터 규칙: 첫 줄 00:00, 3개 이상, 각 10초 이상
function chapterList124(from = 0, to = total()) {
  let points = [
    ...[...musicTracks].map((t) => ({ time: t.start, name: songName89(t) })),
    ...projectMarkers89.map((m) => ({ time: m.time, name: m.name })),
  ]
    .filter((p) => p.time >= from - 0.5 && p.time < to - 1 && String(p.name || "").trim())
    .map((p) => ({ time: Math.max(0, p.time - from), name: String(p.name).trim() }))
    .sort((a, b) => a.time - b.time);
  let list = [];
  for (let p of points) {
    if (!list.length) {
      if (p.time > 1) list.push({ time: 0, name: "인트로" });
      list.push({ ...p, time: list.length ? p.time : 0 });
      continue;
    }
    if (p.time - list.at(-1).time < 10) continue;
    list.push(p);
  }
  // 마지막 챕터도 10초 이상
  while (list.length > 1 && to - from - list.at(-1).time < 10) list.pop();
  return list;
}
