function selftestWav136(seconds = 15) {
  const SR = 48000,
    n = SR * seconds,
    data = new DataView(new ArrayBuffer(44 + n * 4)),
    word = (at, s) => [...s].forEach((ch, i) => data.setUint8(at + i, ch.charCodeAt(0)));
  word(0, "RIFF");
  data.setUint32(4, 36 + n * 4, true);
  word(8, "WAVE");
  word(12, "fmt ");
  data.setUint32(16, 16, true);
  data.setUint16(20, 1, true);
  data.setUint16(22, 2, true);
  data.setUint32(24, SR, true);
  data.setUint32(28, SR * 4, true);
  data.setUint16(32, 4, true);
  data.setUint16(34, 16, true);
  word(36, "data");
  data.setUint32(40, n * 4, true);
  const chords = [
    [261.6, 329.6, 392],
    [220, 261.6, 329.6],
    [174.6, 220, 261.6],
    [196, 246.9, 293.7],
  ];
  for (let i = 0; i < n; i++) {
    let t = i / SR,
      beat = t % 0.5,
      ch = chords[Math.floor(t / 2) % 4],
      v = 0;
    for (let f of ch) v += Math.sin(2 * Math.PI * f * t) * 0.09;
    v += Math.sin(2 * Math.PI * (55 + 60 * Math.exp(-beat * 30)) * beat) * Math.exp(-beat * 9) * 0.45;
    let l = Math.max(-1, Math.min(1, v * (1 + 0.1 * Math.sin(t)))),
      r = Math.max(-1, Math.min(1, v * (1 - 0.1 * Math.sin(t))));
    data.setInt16(44 + i * 4, l * 32767, true);
    data.setInt16(46 + i * 4, r * 32767, true);
  }
  return new File([data.buffer], "점검용-음악.wav", { type: "audio/wav" });
}
const sleep136 = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitIdle136(limit = 60000) {
  let t0 = realNow124();
  await sleep136(200);
  while (busy && realNow124() - t0 < limit) await sleep136(200);
}
