// v142 ② 무료 사진·영상 찾기 (Pexels) — 무료 API 키가 있으면 검색해서 미디어에 바로 넣습니다.
// ═══════════════════════════════════════════════════════════════════
function pexelsKey142() {
  try {
    return (localStorage.getItem("clipHousePexelsKey") || "").trim();
  } catch {
    return "";
  }
}
async function pexelsSearch142(query, kind = "photo", perPage = 15, page = 1) {
  let key = pexelsKey142();
  if (!key) throw Error("Pexels 키가 없어요. 「무료 사진·영상 찾기」에서 키를 넣어 주세요.");
  let base = kind === "video" ? "https://api.pexels.com/videos/search" : "https://api.pexels.com/v1/search",
    url = base + "?query=" + encodeURIComponent(query) + "&per_page=" + perPage + "&page=" + page + "&orientation=landscape&locale=ko-KR",
    res;
  try {
    res = await fetch(url, { headers: { Authorization: key } });
  } catch (e) {
    throw Error("인터넷에 연결할 수 없어요 (" + e.message + ")");
  }
  if (res.status === 401 || res.status === 403) throw Error("Pexels 키가 맞지 않아요. 키를 다시 확인해 주세요.");
  if (res.status === 429) throw Error("Pexels 검색 횟수 한도를 넘었어요. 잠시 뒤 다시 해 주세요.");
  if (!res.ok) throw Error("Pexels 검색 실패 (" + res.status + ")");
  let data = await res.json();
  if (kind === "video")
    return (data.videos || []).map((v) => {
      let files = (v.video_files || []).filter((f) => f.file_type === "video/mp4" && f.width && f.width <= 1920).sort((a, b) => b.width - a.width),
        f = files[0] || v.video_files?.[0];
      return { id: v.id, kind: "video", thumb: v.image, src: f?.link, w: f?.width, h: f?.height, duration: v.duration, credit: "Video by " + (v.user?.name || "Pexels") + " on Pexels", url: v.url };
    }).filter((r) => r.src);
  return (data.photos || []).map((p) => ({ id: p.id, kind: "image", thumb: p.src?.tiny || p.src?.small, src: p.src?.large2x || p.src?.large || p.src?.original, w: p.width, h: p.height, credit: "Photo by " + (p.photographer || "Pexels") + " on Pexels", url: p.url, alt: p.alt || "" }));
}
const pexelsAdded142 = new Map();
async function pexelsDownload142(r, nameHint = "") {
  let key = r.kind + ":" + r.id;
  if (pexelsAdded142.has(key)) return pexelsAdded142.get(key);
  let res = await fetch(r.src);
  if (!res.ok) throw Error("내려받기 실패 (" + res.status + ")");
  let blob = await res.blob(),
    ext = r.kind === "video" ? "mp4" : "jpg",
    base = (nameHint || r.alt || "pexels").replace(/[\\/:*?"<>|]/g, "").slice(0, 40).trim() || "pexels",
    file = new File([blob], base + "-pexels-" + r.id + "." + ext, { type: r.kind === "video" ? "video/mp4" : "image/jpeg" }),
    loaded = await load(file, r.kind),
    item = storeMedia(file, { ...loaded, name: file.name, kind: r.kind });
  if (r.kind === "video") loaded.el?.pause?.();
  item.credit142 = r.credit;
  item.sourceUrl142 = r.url;
  pexelsAdded142.set(key, item);
  return item;
}
