// ── 고른 옵션 구간을 키보드로 옮기기 (v145) ───────────────────────────────
//   ← → : 0.1초씩 이동 · Shift : 1초씩 · Alt + ← → : 끝(길이)만 조절
//   (옵션 구간을 고르지 않았을 때는 예전처럼 주황 줄이 움직입니다)
window.addEventListener("keydown", (e) => {
  if (!["ArrowLeft", "ArrowRight"].includes(e.key) || !editorIsVisible() || busy || projectOperation) return;
  if (/INPUT|TEXTAREA|SELECT/.test(e.target.tagName) || e.target.isContentEditable) return;
  let sel = selectedTimelineOption;
  if (!sel || !clips.includes(sel.c)) return;
  let item = timingItems(sel.c).find((i) => i.key === sel.key && (i.layer?.id || i.key) === sel.id);
  if (!item) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  let c = sel.c,
    r = optionRange(c, item.key, item.layer),
    step = (e.shiftKey ? 1 : 0.1) * (e.key === "ArrowLeft" ? -1 : 1),
    L = length(c),
    start = r.start,
    end = r.end;
  if (e.altKey) end = Math.min(L, Math.max(start + 0.05, end + step));
  else {
    start = Math.max(0, Math.min(L - (r.end - r.start), r.start + step));
    end = start + (r.end - r.start);
  }
  remember();
  writeTiming(c, item.key, item.layer, start, end);
  render();
  draw();
  status(item.label + " · " + start.toFixed(1) + "초 ~ " + end.toFixed(1) + "초 (← → 이동 · Shift 1초 · Alt 길이)");
}, true);


// ── 가벼운 프로젝트 파일 + 원본 다시 연결 (v146) ───────────────────────────
//   큰 음악·사진은 파일 안에 담지 않고 이름만 적어 둡니다 (파일이 아주 작아짐).
//   불러올 때 원본이 든 폴더(또는 파일)를 고르면 이름으로 찾아 자동 연결합니다.
async function exportLightProjectFile146() {
  if (busy || projectOperation) return;
  pause();
  operationLock(true);
  homeStatus("가벼운 프로젝트 파일을 준비합니다…");
  try {
    let packed = await packProject89(await snapshotProject(), { light: true }),
      linked = packed.mediaFiles.filter((f) => f.link).length;
    download(
      new Blob([JSON.stringify(packed)], { type: "application/json" }),
      packed.name.replace(/[\/:*?"<>|]/g, "_") + ".light.clipmood.json",
    );
    let msg = "가벼운 프로젝트 저장 · 원본 " + linked + "개는 이름만 적었어요. 불러올 때 원본 폴더를 골라 주세요.";
    status(msg);
    homeStatus(msg);
  } catch (e) {
    status(e.message);
    homeStatus(e.message);
  } finally {
    operationLock(false);
  }
}
function relinkKey146(name) {
  return String(name || "").normalize("NFC").trim().toLowerCase();
}
function relinkMatch146(links, files, found) {
  let byName = new Map();
  for (let f of files) {
    let k = relinkKey146(f.name);
    if (!byName.has(k)) byName.set(k, []);
    byName.get(k).push(f);
  }
  for (let l of links) {
    if (found.has(l.id) && found.get(l.id).size === l.link.size) continue;
    let list = byName.get(relinkKey146(l.link.name));
    if (!list) continue;
    let best = list.find((f) => f.size === l.link.size) || list[0];
    if (!found.has(l.id) || best.size === l.link.size) found.set(l.id, best);
  }
  return found;
}
function relinkDialog146(data, preFiles) {
  let links = data.mediaFiles.filter((f) => f?.link && typeof f.link.name === "string"),
    found = new Map(),
    box = document.createElement("div");
  // v148: 폴더째 열기로 이미 파일을 받았으면, 다 찾았을 때 창 없이 바로 엽니다.
  if (preFiles?.length) {
    relinkMatch146(links, [...preFiles], found);
    if (links.every((l) => found.has(l.id))) return Promise.resolve(found);
  }
  box.className = "export-dialog123 relink146";
  box.innerHTML = `<div class="export-box123 relink-box146" role="dialog" aria-modal="true">
  <div class="export-head123"><b>📂 원본 파일 연결</b><button type="button" class="export-close123" aria-label="닫기">✕</button></div>
  <p class="relink-note146">이 프로젝트는 <b>가벼운 저장 파일</b>이라 음악·사진 원본이 들어 있지 않아요.<br>원본이 들어 있는 <b>폴더를 고르면</b> 이름으로 찾아 자동으로 연결해요. 폴더가 여러 곳이면 하나씩 차례로 고르세요.<br>창이 안 뜨면 <b>폴더를 이 창에 끌어다 놓거나</b>, 「파일 선택」에서 <b>Ctrl+A</b>로 전부 고르세요.</p>
  <div class="relink-actions146"><button type="button" data-a="folder" class="primary">📁 폴더 선택</button><button type="button" data-a="files">📄 파일 선택</button><span class="relink-count146"></span></div>
  <ul class="relink-list146"></ul>
  <div class="export-actions123"><button type="button" class="export-cancel123">취소</button><button type="button" data-a="skip" class="relink-skip146">없는 파일은 빼고 열기</button><button type="button" data-a="open" class="primary">불러오기</button></div>
  <input type="file" data-i="folder" webkitdirectory multiple hidden><input type="file" data-i="files" multiple hidden>
</div>`;
  document.body.append(box);
  let list = box.querySelector(".relink-list146"),
    count = box.querySelector(".relink-count146"),
    openBtn = box.querySelector('[data-a="open"]'),
    skipBtn = box.querySelector('[data-a="skip"]');
  function paint() {
    let ok = links.filter((l) => found.has(l.id)).length,
      missing = links.filter((l) => !found.has(l.id));
    count.textContent = "연결됨 " + ok + " / " + links.length;
    openBtn.disabled = ok < links.length;
    skipBtn.hidden = ok === links.length || ok === 0;
    list.innerHTML = "";
    for (let l of [...missing, ...links.filter((l) => found.has(l.id))].slice(0, 400)) {
      let li = document.createElement("li");
      li.className = found.has(l.id) ? "ok" : "miss";
      li.textContent = (found.has(l.id) ? "✓ " : "✕ ") + l.link.name;
      list.append(li);
    }
  }
  let autoOpen148 = null;
  function add(files) {
    relinkMatch146(links, [...files], found);
    paint();
    // v148: 전부 찾으면 「불러오기」를 안 눌러도 바로 엽니다.
    if (links.every((l) => found.has(l.id)) && autoOpen148) {
      count.textContent = "연결 완료! 여는 중…";
      setTimeout(() => autoOpen148(), 400);
    }
  }
  box.querySelector('[data-i="folder"]').onchange = (e) => add(e.target.files);
  box.querySelector('[data-i="files"]').onchange = (e) => add(e.target.files);
  box.addEventListener("dragover", (e) => e.preventDefault());
  box.addEventListener("drop", async (e) => {
    e.preventDefault();
    // 폴더를 통째로 끌어다 놓아도 안의 파일을 모두 읽습니다 (v147).
    let entries = [...(e.dataTransfer.items || [])].map((i) => i.webkitGetAsEntry?.()).filter(Boolean);
    if (!entries.length) return add(e.dataTransfer.files);
    count.textContent = "폴더를 읽는 중…";
    let out = [];
    async function walk(en, depth) {
      if (en.isFile) out.push(await new Promise((r) => en.file(r, () => r(null))));
      else if (en.isDirectory && depth < 4) {
        let reader = en.createReader(),
          batch;
        do {
          batch = await new Promise((r) => reader.readEntries(r, () => r([])));
          for (let c of batch) await walk(c, depth + 1);
        } while (batch.length);
      }
    }
    for (let en of entries) await walk(en, 0);
    add(out.filter(Boolean));
  });
  // v147: 크롬의 폴더 고르기 창(showDirectoryPicker)을 먼저 쓰고, 안 되면 예전 방식으로 엽니다.
  async function pickFolder147() {
    if (window.showDirectoryPicker && window.self === window.top) {
      let dir;
      try {
        dir = await window.showDirectoryPicker({ id: "cliphouse-relink", mode: "read" });
      } catch (err) {
        if (err?.name === "AbortError") return;
        dir = null;
      }
      if (dir) {
        count.textContent = "폴더를 읽는 중…";
        let out = [];
        for await (let h of dir.values()) if (h.kind === "file") out.push(await h.getFile());
        add(out);
        return;
      }
    }
    box.querySelector('[data-i="folder"]').click();
  }
  if (preFiles?.length) add([]);
  paint();
  window.__relink146 = { add, found, links };
  return new Promise((resolve) => {
    function close(value) {
      box.remove();
      delete window.__relink146;
      resolve(value);
    }
    autoOpen148 = () => close(found);
    box.addEventListener("click", (e) => {
      // v148: 바깥 어두운 곳을 눌러도 닫히지 않게 (✕ / 취소로만 닫기)
      if (e.target.closest(".export-close123, .export-cancel123")) return close(null);
      let a = e.target.closest("button")?.dataset.a;
      if (a === "folder") pickFolder147();
      if (a === "files") box.querySelector('[data-i="files"]').click();
      if (a === "open" && found.size >= links.length) close(found);
      if (a === "skip") {
        // 없는 원본은 프로젝트에서 빼고 엽니다.
        let gone = new Set(links.filter((l) => !found.has(l.id)).map((l) => l.id));
        data.mediaFiles = data.mediaFiles.filter((f) => !gone.has(f.id));
        data.clips = data.clips.filter((c) => !gone.has(c.media));
        if (data.musicTracks) data.musicTracks = data.musicTracks.filter((t) => !gone.has(t.media));
        if (data.music && gone.has(data.music.media)) data.music = null;
        if (data.mediaLibrary) data.mediaLibrary = data.mediaLibrary.filter((m) => !gone.has(m.file));
        close(found);
      }
    });
  });
}
