// 종류 탭에 개수 · 예제 버튼은 비어 있을 때만 · 선택 막대는 고를 때만
function mediaChrome155() {
  let counts = { 전체: mediaCatalog.length, 음악: 0, 이미지: 0, 영상: 0 };
  for (let m of mediaCatalog) counts[m.kind === "audio" ? "음악" : m.kind === "image" ? "이미지" : "영상"]++;
  for (let b of document.querySelectorAll("#mediaKindTabs button")) {
    let key = b.dataset.kind155 || b.textContent.replace(/\s*\d+$/, "").trim();
    b.dataset.kind155 = key;
    let n = counts[key] ?? 0,
      want = key + (n ? " " + n : "");
    if (b.textContent !== want) {
      b.textContent = key;
      if (n) {
        let s = document.createElement("small");
        s.textContent = n;
        b.append(" ", s);
      }
    }
  }
  for (let card of $("assets").children) {
    if (!card.mediaItemId) continue;
    let item = mediaCatalog.find((m) => m.id === card.mediaItemId);
    if (item && card.dataset.kind155 !== item.kind) card.dataset.kind155 = item.kind;
  }
  let onMedia = activeMenu() === "미디어";
  let demo = document.querySelector(".workspace > aside button.demo");
  if (demo) demo.hidden = !onMedia;
  for (let w of document.querySelectorAll(".media-head155, .media-filter155")) w.hidden = !onMedia;
  let tools = $("mediaBatchTools");
  if (tools) {
    let n = selectedMediaIds.size;
    tools.classList.toggle("has-sel155", n > 0);
    tools.hidden = !mediaCatalog.length || !onMedia;
    let count = $("mediaBatchCount");
    if (count) count.textContent = n ? n + "개 선택" : "";
    let add = $("addMediaBatch");
    if (add && !add.dataset.v155) {
      add.dataset.v155 = "1";
      add.textContent = "＋ 타임라인에 넣기";
    }
  }
}
{
  const umsui155 = updateMediaSelectionUI;
  updateMediaSelectionUI = function (...a) {
    let r = umsui155.apply(this, a);
    try {
      mediaChrome155();
    } catch {}
    return r;
  };
  new MutationObserver(() => mediaChrome155()).observe($("assets"), { childList: true });
  mediaChrome155();
}
// ③ 오른쪽 설정 묶음 접고 펴기 (제목을 누르면 접혀요 · 기억해요)
function collapsible155(root = document) {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem("clipHouseFold155") || "{}");
  } catch {}
  for (let h of root.querySelectorAll("aside.settings .card > h3, aside.settings .layer-panel > h3")) {
    if (h.dataset.fold155 || !h.textContent.trim()) continue;
    let box = h.parentElement,
      key = h.textContent.replace(/\s+\S*\d.*$/, "").trim().slice(0, 30);
    h.dataset.fold155 = key;
    h.classList.add("fold-head155");
    h.tabIndex = 0;
    h.title = "눌러서 접기 / 펼치기";
    if (saved[key]) box.classList.add("folded155");
    let toggle = () => {
      box.classList.toggle("folded155");
      try {
        let s = JSON.parse(localStorage.getItem("clipHouseFold155") || "{}");
        s[key] = box.classList.contains("folded155");
        localStorage.setItem("clipHouseFold155", JSON.stringify(s));
      } catch {}
    };
    h.addEventListener("click", (e) => {
      if (e.target.closest("button, input, select, a")) return;
      toggle();
    });
    h.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        toggle();
      }
    });
  }
}
collapsible155();
setInterval(() => {
  if (editorIsVisible()) collapsible155();
}, 2000);

