  m.filter = "blur(" + Math.max(1, Math.round(Math.max(W, H) / 700)) + "px)";
  m.drawImage(maskBitmap, 0, 0, W, H);
  // 가장자리를 조금 또렷하게 (흐린 알파를 대비 올리기)
