    name = "목소리 · " + tq187("tts187-text").value.trim().slice(0, 14).replace(/[\\/:*?"<>|\n]/g, " ") + ".webm",
    dt = new DataTransfer();
  dt.items.add(new File([blob], name, { type: "audio/webm" }));
  $("file").files = dt.files;
  await $("file").onchange();
