// v188 · 📸 사진 살아나기 (입체 사진) — 사람은 앞에, 배경은 뒤에 두고 서로 다르게 움직여 3D처럼 보이게
const live188 = new WeakMap(); // 장면 → { bg, fg } | "busy"
function fillHoles188(img, mask) {
  let W = mask.width,
    H = mask.height,
    mk = (w, h) => {
      let c = document.createElement("canvas");
      c.width = w;
      c.height = h;
      return c;
    };
  // 사람 가장자리를 조금 넓힌 가면
  let wide = mk(W, H),
    wx = wide.getContext("2d");
  wx.filter = "blur(" + Math.round(Math.max(W, H) / 120) + "px)";
  wx.drawImage(mask, 0, 0);
  wx.filter = "none";
  let d = wx.getImageData(0, 0, W, H),
    p = d.data;
  for (let i = 3; i < p.length; i += 4) p[i] = p[i] > 8 ? 255 : 0;
  wx.putImageData(d, 0, 0);
  // 사람 자리를 뚫은 배경
  let bg = mk(W, H),
    bx = bg.getContext("2d");
  bx.drawImage(img, 0, 0, W, H);
  bx.globalCompositeOperation = "destination-out";
  bx.drawImage(wide, 0, 0);
  bx.globalCompositeOperation = "source-over";
  // 구멍을 주변 색으로 점점 크게 흐려서 메우기
  let m = Math.max(W, H);
  for (let r of [0.01, 0.025, 0.06, 0.12, 0.25]) {
    let layer = mk(W, H),
      lx = layer.getContext("2d");
    lx.filter = "blur(" + Math.max(2, Math.round(m * r)) + "px)";
    for (let k = 0; k < 4; k++) lx.drawImage(bg, 0, 0);
    lx.filter = "none";
    bx.globalCompositeOperation = "destination-over";
    bx.drawImage(layer, 0, 0);
    bx.globalCompositeOperation = "source-over";
  }
  bx.globalCompositeOperation = "destination-over";
  bx.filter = "blur(" + Math.round(m * 0.05) + "px)";
  bx.drawImage(img, 0, 0, W, H);
  bx.filter = "none";
  bx.globalCompositeOperation = "source-over";
  return bg;
}
async function prepareLive188(c) {
  if (live188.get(c) && live188.get(c) !== "fail") return live188.get(c);
  live188.set(c, "busy");
  try {
    let mask = await personMask185(c.el),
      fg = cutout185(c.el, mask),
      bg = fillHoles188(c.el, mask),
      r = { bg, fg };
    live188.set(c, r);
    draw();
    return r;
  } catch (e) {
    live188.set(c, "fail");
    throw e;
  }
}
const baseRenderPro188 = renderProMedia;
renderProMedia = function (c, e, w, h, s, dx, dy, rotate, local) {
  let src = c && (clips.find((x) => x.el === e) || (c.el === e ? c : null));
  if (src?.live188On && src.kind === "image") {
    let L = live188.get(src);
    if (!L) prepareLive188(src).catch(() => {});
    if (L && typeof L === "object") {
      let len = Math.max(0.5, length(src) || 5),
        p = Math.max(0, Math.min(1, (local || 0) / len)),
        ease = p * p * (3 - 2 * p),
        amt = src.live188Amt ?? 1,
        W = canvas.width,
        dir = src.live188Dir ?? 1;
      baseRenderPro188(c, L.bg, w, h, s * (1.07 + 0.07 * ease * amt), (dx || 0) - dir * (ease - 0.5) * W * 0.035 * amt, dy || 0, rotate, local);
      return baseRenderPro188(c, L.fg, w, h, s * (1.0 + 0.025 * ease * amt), (dx || 0) + dir * (ease - 0.5) * W * 0.012 * amt, (dy || 0) - ease * 4 * amt, rotate, local);
    }
  }
  return baseRenderPro188(c, e, w, h, s, dx, dy, rotate, local);
};
const baseProps188 = props;
props = function (c) {
  let r = baseProps188(c);
  if (r && c?.live188On) {
    r.live188On = true;
    r.live188Dir = c.live188Dir ?? 1;
  }
  return r;
};
// 배경 지우기 창 맨 위에 「사진 살아나기」 단추
