    P={x:0,by:0,lean:0,tilt:0,flip:1,arms:[],hands:null,feet:[],hearts:false};
  let lift=[0,0],fx=[-10,10];
  const arm=(a,e)=>[a,e];
  if(move==="bounce"){P.by=2.2*dip;P.tilt=.07*s;P.lean=.035*half;P.x=2*half;
    P.arms=[-1,1].map(k=>arm(.6+.45*Math.sin(ph+(k>0?Math.PI:0)),.8));}
  else if(move==="wave"){P.x=3.5*half;P.lean=.07*half;P.tilt=-.06*half;P.by=1.5*dip;
    P.arms=[-1,1].map(k=>arm(1.5+.5*Math.sin(ph-k*1.1),.97));}
  else if(move==="disco"){P.x=4*half;P.lean=.09*half;P.tilt=.05*half;P.by=2.5*dip;
    P.arms=[-1,1].map(k=>{const L=(1+k*half)/2;return arm(.5+2.15*L,.93);});}
  else if(move==="jump"){const j=Math.max(0,s)**2,crouch=Math.max(0,-s);P.by=-15*j+4*crouch;lift=[11*j,11*j];
    P.arms=[-1,1].map(()=>arm(.45+2.2*j,.95));P.tilt=.04*half;}
  else if(move==="side"){P.x=7*half;P.lean=-.05*half;P.by=2*dip;
    lift=[-1,1].map(k=>6*Math.max(0,k*s));fx=[-1,1].map(k=>k*10+5*half);
    P.arms=[-1,1].map(k=>arm(.55+.9*Math.max(0,k*s),.88));P.tilt=.05*half;}
  else if(move==="heart"){P.x=2.5*half;P.lean=.05*half;P.tilt=.12*half;P.by=1.5*dip;P.hearts=true;
    P.hands=[-1,1].map(k=>[k*5,20+1.5*s]);}
  else if(move==="spin"){P.x=4*half;P.lean=.13*half;P.tilt=.1*half;P.by=2*dip;P.flip=.94+.06*Math.cos(ph);
    P.arms=[-1,1].map(k=>arm(1.35+.95*k*half,.94));}
